    # ── Guards the services also enforce (prompt-v1 §8.6, §6.7 PT8, §6.10 M16) ──
    op.execute("""
    CREATE OR REPLACE FUNCTION atmos_team_size_guard() RETURNS trigger AS $$
    DECLARE n int; cap int;
    BEGIN
      SELECT max_members INTO cap FROM teams WHERE id = NEW.team_id FOR UPDATE;
      SELECT count(*) INTO n FROM team_members WHERE team_id = NEW.team_id;
      IF n >= cap THEN
        RAISE EXCEPTION 'team.full' USING ERRCODE = 'check_violation';
      END IF;
      RETURN NEW;
    END $$ LANGUAGE plpgsql;
    """)
    op.execute(
        "CREATE TRIGGER team_size_guard BEFORE INSERT ON team_members FOR EACH ROW EXECUTE FUNCTION atmos_team_size_guard()"
    )
    op.execute("""
    CREATE OR REPLACE FUNCTION atmos_ledger_append_only() RETURNS trigger AS $$
    BEGIN
      IF TG_OP = 'DELETE' AND current_setting('atmos.allow_ledger_delete', true) = 'on' THEN
        RETURN OLD;
      END IF;
      RAISE EXCEPTION 'points_ledger is append-only';
    END $$ LANGUAGE plpgsql;
    """)
    op.execute(
        "CREATE TRIGGER ledger_append_only BEFORE UPDATE OR DELETE ON points_ledger FOR EACH ROW EXECUTE FUNCTION atmos_ledger_append_only()"
    )
    op.execute("""
    CREATE OR REPLACE FUNCTION atmos_credit_lot_guard() RETURNS trigger AS $$
    BEGIN
      IF OLD.state IN ('sold','retired') AND NEW.sold_to_company_id IS DISTINCT FROM OLD.sold_to_company_id THEN
        RAISE EXCEPTION 'credit_lot.already_sold';
      END IF;
      IF OLD.state = 'retired' AND NEW.state <> 'retired' THEN
        RAISE EXCEPTION 'credit_lot.retired_is_final';
      END IF;
      IF OLD.state = 'sold' AND NEW.state NOT IN ('sold','retired') THEN
        RAISE EXCEPTION 'credit_lot.sold_is_final';
      END IF;
      RETURN NEW;
    END $$ LANGUAGE plpgsql;
    """)
    op.execute(
        "CREATE TRIGGER credit_lot_guard BEFORE UPDATE ON credit_lots FOR EACH ROW EXECUTE FUNCTION atmos_credit_lot_guard()"
    )
